;; Luigi's Mirror Race (the mini game that frees him): The Lost Levels' 1-1, from our own converted
;; ll-1-1.map, eased for a one-life race (race.test.ts lists every change; human-sim.test.ts races
;; a careful player over it). race.ts loads it with ?raw, so it is not in the level library, the dev
;; level select or the campaign.
id: luigi-race
name: MIRROR RACE
world: 1
stage: 1
theme: overworld
music: overworld
time: 400
start: 2,12
startMode: stand
camera: scroll

